import{_ as n,o as r,c as a,a3 as i}from"./chunks/framework.-MjGFDw0.js";const u=JSON.parse('{"title":"Wie voert de zorg uit?","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"nurse/wie.md","filePath":"nurse/wie.md","lastUpdated":1795772800000}'),t={name:"nurse/wie.md"};function o(d,e,g,l,s,p){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="wie-voert-de-zorg-uit" tabindex="-1">Wie voert de zorg uit? <a class="header-anchor" href="#wie-voert-de-zorg-uit" aria-label="Permalink to &quot;Wie voert de zorg uit?&quot;">​</a></h1><p>Het prestatiebestand legt vast welke praktijk de zorg factureert en welke zorgverlener elke zorg effectief uitvoerde.</p><h2 id="de-praktijk" tabindex="-1">De praktijk <a class="header-anchor" href="#de-praktijk" aria-label="Permalink to &quot;De praktijk&quot;">​</a></h2><p>De praktijk is de <strong>vereniging</strong> in het bestand. Ze wordt geïdentificeerd door de verenigingscode op de node <a href="/pr-preview/pr-13/nurse/nodes#node-vereniging">vereniging</a>.</p><ul><li>De verenigingscode is verplicht en wordt door TDM3 toegekend. Vraag ze aan bij TDM3.</li><li>Op basis van de verenigingscode koppelt TDM3 de zorg aan de contracten, de financiële afspraken en de afscherming van de gegevens van de praktijk.</li><li>Per praktijk en per facturatiemaand levert het pakket normaal gezien één bestand. Zie <a href="/pr-preview/pr-13/nurse/hoe#aanlevering">Aanlevering</a>.</li></ul><p>Het prestatiebestand is niet het facturatiebestand voor het ziekenfonds. Het pakket levert per praktijk of team (verenigingscode) aan. TDM3 groepeert die bestanden zelf onder het juiste derdebetalersnummer, in één of meerdere facturatiebestanden. Zo kan een team aanleveren en gefactureerd worden zodra het klaar is. De verenigingscode is de sleutel waarmee TDM3 de bestanden aan de praktijk koppelt.</p><h2 id="de-zorgverlener" tabindex="-1">De zorgverlener <a class="header-anchor" href="#de-zorgverlener" aria-label="Permalink to &quot;De zorgverlener&quot;">​</a></h2><p>Op elke <a href="/pr-preview/pr-13/nurse/nodes#node-uitgevoerdezorg">uitgevoerdezorg</a> staat de zorgverlener die de zorg effectief uitvoerde.</p><ul><li><strong>rizivnummerverpleegkundige</strong>: het RIZIV-nummer van de verpleegkundige, voorafgegaan door 0 (niet geconventioneerd) of 1 (geconventioneerd).</li><li><strong>naamverpleegkundige</strong>: de naam van de verpleegkundige.</li><li><strong>rizivnummerzorgkundige</strong> en <strong>naamzorgkundige</strong>: het RIZIV-nummer en de naam van de zorgkundige, wanneer een zorgkundige de zorg uitvoerde.</li></ul><p>TDM3 koppelt de zorgverlener aan de contracten op basis van de verenigingscode, het RIZIV-nummer en de facturatiemaand.</p><h2 id="zorgkundigen-bij-palliatieve-zorg-vanaf-01-2024" tabindex="-1">Zorgkundigen bij palliatieve zorg (vanaf 01/2024) <a class="header-anchor" href="#zorgkundigen-bij-palliatieve-zorg-vanaf-01-2024" aria-label="Permalink to &quot;Zorgkundigen bij palliatieve zorg (vanaf 01/2024)&quot;">​</a></h2><p>Vanaf prestatiedatum 01/01/2024 mogen zorgkundigen ook ingezet worden bij de uitvoering van palliatieve zorgen, op voorwaarde dat een zitting door een verpleegkundige is uitgevoerd.</p><p>Hierop bestaan uitzonderingen: wanneer de patiënt overlijdt, of bij een opname in of ontslag uit een zorginstelling. Dan kan de verpleegassistent, verpleegkundige of zorgkundige de enige zijn, of kan een forfait C/PC gefactureerd worden wanneer er maar één zitting heeft plaatsgevonden.</p><p>Daarom is de betekenis van het veld <a href="/pr-preview/pr-13/nurse/nodes#node-uitgevoerdezorg">uitgevoerdezorg.ZHOpname</a> uitgebreid met de waarden 2, 3 en 4:</p><ul><li>0 = geen opname</li><li>1 = opname in ziekenhuis</li><li><strong>2 = ontslag uit ziekenhuis</strong></li><li><strong>3 = opname in andere verzorgingsinstelling</strong></li><li><strong>4 = ontslag uit andere verzorgingsinstelling</strong></li></ul><p>Bij waarde 1 en 2 vermeldt TDM3 de pseudocode <a href="https://webappsa.riziv-inami.fgov.be/Nomen/nl/426613" target="_blank" rel="noreferrer">426613</a> als betrekkelijke verstrekking in de facturatie. De waarden zijn ook van belang voor het correct factureren van palliatieve forfaits en van een forfait PC/C in de uitzonderingssituaties.</p>',16)])])}const k=n(t,[["render",o]]);export{u as __pageData,k as default};
